package cn.sutone.cut.api.dto.script;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Structural reader for the finite schema subset generated by generate_b1_contracts.py.
 * It is deliberately not a general JSON Schema engine. Unknown keywords fail closed.
 */
final class B1Structure {
    private static final Set<String> KEYWORDS = Set.of("$schema", "$id", "$defs", "$ref", "title",
            "description", "type", "properties", "required", "additionalProperties", "anyOf",
            "const", "enum", "items", "minItems", "minLength", "pattern", "minimum", "maximum");
    private static final JsonNode SCHEMA = load();

    private B1Structure() {}

    private static JsonNode load() {
        try (var input = B1Structure.class.getResourceAsStream("/contracts/script-contract-bundle-v1.schema.json")) {
            if (input == null) throw new IllegalStateException("B1 schema resource missing");
            return new ObjectMapper().readTree(input);
        } catch (IOException error) {
            throw new IllegalStateException("B1 schema cannot be loaded", error);
        }
    }

    static void validate(String name, JsonNode value) {
        validate(name.equals("ScriptContractBundleV1") ? SCHEMA : SCHEMA.path("$defs").path(name), value);
    }

    private static void check(boolean value, String message) {
        if (!value) throw new IllegalArgumentException("B1 structure: " + message);
    }

    private static void validate(JsonNode schema, JsonNode value) {
        check(!schema.isMissingNode(), "unknown definition");
        schema.fieldNames().forEachRemaining(key -> check(KEYWORDS.contains(key), "unsupported keyword " + key));
        if (schema.has("$ref")) {
            String ref = schema.path("$ref").asText();
            check(ref.startsWith("#/$defs/"), "external reference");
            validate(SCHEMA.path("$defs").path(ref.substring(8)), value);
            return;
        }
        if (schema.has("anyOf")) {
            for (JsonNode branch : schema.get("anyOf")) {
                try { validate(branch, value); return; }
                catch (IllegalArgumentException ignored) { /* try the next declared branch */ }
            }
            throw new IllegalArgumentException("B1 structure: no matching union branch");
        }
        check(value != null, "missing value");
        if (schema.has("const")) check(schema.get("const").equals(value), "constant mismatch");
        if (schema.has("enum")) {
            boolean found = false;
            for (JsonNode allowed : schema.get("enum")) found |= allowed.equals(value);
            check(found, "unknown enum value");
        }
        String kind = schema.path("type").asText();
        switch (kind) {
            case "object" -> {
                check(value.isObject(), "expected object");
                for (JsonNode required : schema.path("required")) check(value.has(required.asText()), "missing " + required.asText());
                Set<String> allowed = new HashSet<>();
                schema.path("properties").fieldNames().forEachRemaining(allowed::add);
                if (!schema.path("additionalProperties").asBoolean(true))
                    value.fieldNames().forEachRemaining(key -> check(allowed.contains(key), "unknown field " + key));
                for (String key : allowed) if (value.has(key)) validate(schema.get("properties").get(key), value.get(key));
            }
            case "array" -> {
                check(value.isArray(), "expected array");
                check(value.size() >= schema.path("minItems").asInt(0), "too few items");
                for (JsonNode item : value) validate(schema.get("items"), item);
            }
            case "string" -> {
                check(value.isTextual(), "expected string");
                String text = value.asText();
                check(text.codePointCount(0, text.length()) >= schema.path("minLength").asInt(0), "string too short");
                if (schema.has("pattern")) check(Pattern.compile(schema.get("pattern").asText()).matcher(text).find(), "pattern mismatch");
            }
            case "integer", "number" -> {
                check(value.isNumber() && Double.isFinite(value.asDouble()), "expected finite number");
                double number = value.asDouble();
                if (kind.equals("integer")) check(number == Math.rint(number), "expected integer");
                if (schema.has("minimum")) check(number >= schema.get("minimum").asDouble(), "below minimum");
                if (schema.has("maximum")) check(number <= schema.get("maximum").asDouble(), "above maximum");
            }
            case "boolean" -> check(value.isBoolean(), "expected boolean");
            case "null" -> check(value.isNull(), "expected null");
            case "" -> { /* const/enum-only schema */ }
            default -> throw new IllegalArgumentException("B1 structure: unsupported type " + kind);
        }
    }
}
